import org.jsoup.Jsoup

@Composable
fun DetailScreenContent(
    modifier: Modifier = Modifier,
    darkMode: Boolean = isSystemInDarkTheme(),
    state: LazyListState,
    title: String,
    author: ArticleAuthor,
    content: String
) {
    val rememberContent = remember(Jsoup.parse(content).body()::childNodes)

    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .then(modifier),
        contentPadding = PaddingValues(horizontal = 16.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
        state = state
    ) {
        item(
            key = DetailScreenKey.HEADER,
            contentType = DetailScreenKey.AUTHOR
        ) {
            Text(
                text = title,
                style = MaterialTheme.typography.headlineSmall,
                color = MaterialTheme.colorScheme.onSurface
            )
        }
        item(
            key = DetailScreenKey.AUTHOR,
            contentType = DetailScreenKey.AUTHOR
        ) {
            Text(
                text = author.nickname,
                modifier = Modifier.fillMaxSize(),
                style = MaterialTheme.typography.titleSmall
            )
        }
        parserBodyContent(
            darkMode = darkMode,
            list = rememberContent
        )
    }
}

@Preview(showBackground = true, device = "id:pixel_9_pro_xl")
@Composable
fun DetailScreenContentPreview() {
    val state = rememberLazyListState()
    DetailScreenContent(
        title = "社区速递 068 | 你没见过的社区文章、一周最热评、派友的控制中心",
        author = ArticleAuthor(
            nickname = "Matrix机器人"
        ),
        content = """
            <p>除了首页时间流和侧栏的精选展位，少数派 Matrix 社区还有很多优秀内容因条件所限无法得到有效曝光，因此我们决定重启 Matrix 周报，并在此基础上添加更多社区内容、作者投稿新玩意呈现给大家。</p><hr/><h2>🔥一周热评</h2><p>来自文章<a href=\"https://sspai.com/post/93676\">《“iPad mini 换新记：一场消费与理性的博弈”》</a>：</p><blockquote><p><strong>知道分子吴先先 </strong>(+3) 「尽管费用计算上不完全符合逻辑」，原来大家在以旧换新的时候，都喜欢用这种明知道不对，但显得花钱少的计算方法哈哈哈：）</p><p>我有一部用了四年的iphone12，除了电池续航没有太多问题。原本准备去店里+七八百换一个电池坚持一年。结果意外发现以旧换新有补贴，最后折抵了1300，换了一台原价5499的iphone16。所以我把自己新买的手机定价为：5500（原价）-1300（旧机折抵）-800（换电池费）=3400元。</p><p>考虑到换完电池的iphone12折旧费用几乎=0，而一年后iphone16折旧费3000+，四舍五入认为第一年这个手机免费用。简直是同样的计算思路了。</p></blockquote><p>来自文章<a href=\"https://sspai.com/post/92905\">《向山出发，日本表银座纵走攻略》</a>：</p><blockquote><p><strong>常年奶叔 </strong>(+4) 我之前也简单研究了这个行程，实在对登山素人不太友好，虽然风景很美，但我最终还是放弃了。最后选择了从平汤温泉出发，坐新穗高缆车到半山，然后徒步到山顶西穗山庄，然后向上高地下山，全程4,5个小时，属于比较休闲，同时又能领略原始自然风光。</p><p>西穗山庄休整的时候，有个日本人问我，你这背上的字是什么意思，我日文不会，英文只会基础的，想了半天，我回答说：Rock and Roll</p><p>第二次再去，就是新人按照我给的路线图完成，我带着老少在上高地里平地游览，也是另一种美景。看看11月初是否还有机会再去一次，看看红叶是什么样子。</p></blockquote><p>来自文章<a href=\"https://sspai.com/post/93549\">《视频笔记怎么做？“魔法葫芦”新功能，让Bilibili &amp; YouTube视频学习更高效！》</a>：</p><blockquote><p><strong>o大狼o </strong>(+1) 这个插件有点意思。之前安装的是 Language Reactor 插件用于Youtube的字幕，学外语觉得挺不错，但不知道怎么我一直注册不进去，无法使用更多功能。</p><p>看魔法葫芦也有字幕功能，还能做笔记，去安装了。</p><p>笔记功能小试了一下，如果通过视频上课，这个功能应该很厉害。不过现有的字幕功能比Language Reactor差距挺多，单纯看视频还是用那个插件适合，等到学东西的时候再试试魔法葫芦。</p></blockquote><p>来自文章<a href=\"https://sspai.com/post/93696\">《城市漫步指南：济州岛，需要好天气》</a>：</p><blockquote><p><strong>少数派89088526 </strong>(+0) 去年十一去的济州岛，去了西南线的西归浦，可以试试这条线，有沿海徒步线路，能潜水，还有能看海豚的地方。</p></blockquote><p>来自文章<a href=\"https://sspai.com/post/92847\">《城市漫步指南：拓跋鲜卑，北魏平城》</a>：</p><blockquote><p><strong>AuditoreLeung </strong>(+3) 前些日子刚刚从大同回来，善化寺我也去了，可能赶得比较巧没遇到管拍照的工作人员，但我觉得只要在不破坏文物的情况下，拍照有何不可？毕竟提示牌上面写的都是「禁止使用闪光灯」，而不是「禁止拍照」。相反，悬空寺供奉神像的屋子里面写的就是「禁止拍照」，一开始拍的时候没注意，但后来发现了，出于尊重还是把之前拍的照片删掉了</p></blockquote><p>来自文章<a href=\"https://sspai.com/post/93573\">《不严谨讨论：拿到多少钱，学历才算没贬值》</a>：</p><blockquote><p><strong>别惹小炸毛 </strong>(+16) 说说自己的经历。</p><p>本科毕业后，身边的有些同学选择读研，有些进了大厂。研究生期间恰逢三年疫情，导致读完研之后要么发现本科毕业能进的公司现在研究生也进不去了，就算进去了开的工资也比相较之前少了。</p><p>于是，就发生了读研花了三年的时间，却并没有带来薪资上的提升，而又有几个人从事了科研相关的工作呢，不还是跟本科生一样做开发的工作。所以，对于我们这一批人来说，读研的确发生了学历贬值。</p></blockquote><blockquote><p><strong>文某君 </strong>(+14) 「要看个人的努力，也要看历史的进程……」</p><p>说个我个人视角的趣事，如果我硕士毕业就选择和老婆一起去深圳工作，那么几乎肯定那时候就会在深圳贷款买房子，算算到今天，房产价值也亏去了至少上百万了。就算我找了个大厂工作，差不多也是把工资全赔进去。所以，对我的这种特殊情况而言，选择继续读书起到了一定的「避险」作用。😂</p></blockquote><blockquote><p><strong>VictorHenry </strong>(+0) 个人经历，一个70后</p><p>个人觉得学历没有所谓贬值一说，主要还是大环境里住房影响最大，外来打工， 你成家就要买房，就要还房贷，没法让年轻人从底层开始积攒职业经验（薪水低没法还房贷），起点需要较高些薪水的工作。个人是从工厂助理实习期600，转正1200开始，一直做到公司外贸部主管，然后创业，失败，但是风险管理意识有，基本没有大投入，那个年代只要是大学毕业（无论专科，本科）就业机会特别多，只要肯努力，从底层上升的普通人很多，学历的价值体现需要一个较长的职业过程。</p><p>现在一还是房价问题二是目前大环境不好导致的整体薪资水平低，这两点可能导致有学历贬值的感觉。</p><p>学历只是敲门砖，没有学历连打工机会也没有了（老婆疯狂鸡娃的原因，我带儿子组队打游戏），变现还是靠学识，努力和能力。</p></blockquote><p>来自文章<a href=\"https://sspai.com/post/93805\">《派早报：Firefox 正式版发布二十年》</a>：</p><blockquote><p><strong>日子在长大 </strong>(+18) iOS 18.1 在静置时自动重启，提高破解难度</p><p>如果是真的，那这个好赞，虽然现在已经没啥隐私可言，但作为手机厂商还能尽可能地努力去提高设备隐私安全性，真的是件非常值得表扬的事情吧！</p></blockquote><p>来自文章<a href=\"https://sspai.com/post/93051\">《求索于微观尽头——谈谈我眼中的光刻技术》</a>：</p><blockquote><p><strong>少数派27627702 </strong>(+11) 前fab工程师报到，说的还算比较细，其实可以引入一下光刻胶正性和负性的区别，还有步进式和扫描式光刻机的区别。另外ASML的光刻机还会有有一个计算机群实时计算进行微调每次曝光的光强和时长，当然我没见过这么高级的因为我们还在用1999年生产的尼康i8😅</p></blockquote><p>来自文章<a href=\"https://sspai.com/post/93743\">《本周看什么 | 最近值得一看的 10 部作品》</a>：</p><blockquote><p><strong>潘誉晗 </strong>(+2) 相比较前面几集，《主厨的餐桌：面条》的豆瓣评分其实不算特别漂亮。这一季很明显更倾向于人文的塑造，所以我自己看的时候都有“面条呢！面条呢！”这样的心情。但我确实也很喜欢1/2/4、还有3的最后十分钟。</p><p>第二集的魏桂荣我在今年看《唐人街之味》里有留意到。书里只说是中国姑娘跑到英国来当厨师，纪录片里有做了更详细的介绍。家里没钱，三个女儿，身为老大的她选择放弃学业。出门前拉着妹妹来到厨房，指着一面墙：“姐姐成绩这么好，贴满了一面墙，妳们读书读不好是妳们的问题；让妳们没书读，是姐姐的问题。”她说没学过音乐，但觉得厨房的碰撞声就是音乐。后面来英国开了四家店，给家里造了房子，确实像一些评论说的重男轻女的价值让人觉得很难过，但是她拼出来还是觉得特别好。这一集的推荐人还是扶霞，特别好。</p><p>第一集的胖厨师家里艺术世家，弟弟自学成才N种乐器，他不会意大利语跑意大利学艺，发现了自己。也说这些都是女性的功劳，他要把她们传播出去。</p><p>第四集有人说是某种正确。大概是因为这周看了两本韩江的历史小说，书里有说遭到伤害的那些人没有熬过去。第四集的厨师爸爸也是这样的。所以她所发扬的面食文化，也涵盖了更多的意义。</p><p>所以纠结了一下还是写了详细推荐。如果说不喜欢人文的小伙伴的话就可以不看了。</p></blockquote><p>来自文章<a href=\"https://sspai.com/post/92682\">《大屏全面屏后，智能手机发展真的停滞了吗？—— 手机形态发展简史·终》</a>：</p><blockquote><p><strong>Leobai </strong>(+14) 终于是找到时间整理并且补完了这篇陈年烂稿……现在想想当年的自己真的是充满精力，现在即使勉强有着时间，也没有心力去回头重读一遍当时读过的诸多文章，来让最后的理论分析更加完善一些</p><p>这篇文章在我心里属于是向上探，它仍然延续了老的研究路径，用的文献很多都不一定可靠，最后只是简单套用理论到一个新的领域，没有任何有创见的分析的垃圾，往下走，它似乎又比简单的梳理手机系列发展史，提供不了除后来人的手机综评与主观回忆以外的更多的任何东西稍微好那么一点点</p><p>就这样吧，用这篇文章祭奠我在数码圈的几年，纪念我从2018到2023混迹数码圈的时光。人还有自己各自的生活，我还有自己的路要走，就用这篇文章矫情的告个别。</p><p>原文大多数内容完成于2022年初。</p></blockquote><blockquote><p><strong>Enc3lMag1k </strong>(+10) 鸿篇巨制，作者很厉害。</p><p>提一个文章中没有提到的细节。一般认为MIX开创了全面屏的原因不完全是它的发布会上第一次提出这个概念，而更因为小米为了MIX与谷歌谈判，使得谷歌开放了AOSP中的tile,view与屏幕自适应dpi的限制——换言之，手机的长宽比例可以随心所欲了。</p><p>再配上从未在安卓上出现的一套手势操作，不得不承认小米是这七八年的全面屏浪潮，以及背后众多供应链技术创新的开创者。对于文章最后的问题，我觉得同质化恰恰是发展趋向于完美的印证，而下一步需要等待的就是技术上的变革性创新了。这里的完美更多是成本与盈利与技术的平衡，所谓带着镣铐跳舞。</p><p>但不管怎么说，奥利奥deco就是最烂的潮流，这和行业的稳定没有关系。</p></blockquote><p>来自文章<a href=\"https://sspai.com/post/93614\">《冬天也不用裹成球，这是你需要了解的冬季穿衣指南》</a>：</p><blockquote><p><strong>蓝色风笛 </strong>(+9) 应该注意，ECWCS系统的L1-L7，不是简单的随着温度叠加关系，对于城市内活动，L4用处不大且与L5定位重合、L6（硬壳冲锋衣）维护困难，可以考虑直接用L5替代，L3重型抓绒只承担保暖作用几乎不用来排汗，可以用轻棉服替代</p></blockquote><h3>📒社区摘要</h3><ul><li><strong>PJHubs：</strong>《<a href=\"https://sspai.com/post/92842\">塞上青城，归化绥远</a>》</li><li><strong>mingzzz：</strong>《<a href=\"https://sspai.com/post/93680\">那些磁吸支架</a>》</li><li><strong>唐小黑_zoetblack：</strong>《<a href=\"https://sspai.com/post/93794\">五年度计划</a>》</li><li><strong>SSShooter：</strong>《<a href=\"https://sspai.com/post/93668\">马尔代夫 Maafushivaru 之旅 1 —— 从广州到马累</a>》</li><li><strong>遇事不决点宵夜：</strong>《<a href=\"https://sspai.com/post/93639\">关于写作的思考（一）</a>》</li><li><strong>虹猫酱的呆毛：</strong>《<a href=\"https://sspai.com/post/93521\">为什么是火星？</a>》</li><li><strong>云走惊鹊：</strong>《<a href=\"https://sspai.com/post/93568\">RSS：把注意力的掌控权牢牢握在自己的手中</a>》</li></ul><h2>🆕作者的新玩意</h2><p>为了让作者的投稿尽快与广大读者见面，我们调整了《新玩意》栏目中作者投稿部分的呈现方式和周期，作者投稿的「新玩意」后续会迁移至本栏目。投稿渠道与奖励方式仍与以往完全一致，详情参见文末。我们相信新鲜火热出炉的分享更能赢得大家的喜爱，也欢迎广大读者朋友们踊跃投稿。</p><h3>@手动贩卖机：城市波浪铝合金330g折叠凳</h3><ul><li>入手渠道：淘宝</li><li>入手价格：￥23.95</li></ul><p>为了去另一个城市参加户外音乐节，我考虑到音乐节久站不易，决定入手一个可以拿来坐的物件。</p><p>考虑到以下几点：</p><ol><li>方便个人步行携带，所以排除类似于月亮椅等收纳体积较大的露营椅</li><li>讨厌虫子，为了尽量避免直接接触地面，所以排除野餐垫、蛋槽垫等地垫类产品 <br/>所以，我决定购入一款小巧便携的折叠凳。</li></ol><p>我一番搜索过后，发现竟然有收纳起来和一台 Switch 大小差不多的折叠凳产品，想着市面上的这类产品似乎差别并不大，使用方式几乎无异，都是通过弹力绳将几段金属管组合起来即可使用，就随便购入了一款（下称无名款），入手价格为 12.43 元。</p><p>结果到手之后才发现，虽然金属折叠凳这种产品已经有非常多厂家在生产，但并不是完全没有技术壁垒的，并不是谁做都一样的。</p><p>体验无名款折叠凳的第一感觉是 —— 重。</p><p>即使是我这种对重量不敏感的人，也会马上知道如果背着这张凳子在异地旅游走一天会是一种什么样的体验。</p><figure class=\"image ss-img-wrapper\"><img src=\"https://cdnfile.sspai.com/2024/11/04/7cbfe5d35b6418ac1d103507f5dc766d.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" data-original=\"https://cdnfile.sspai.com/2024/11/04/7cbfe5d35b6418ac1d103507f5dc766d.jpg?imageView2/2/format/webp\"/><figcaption>实测重量：715.9g（已去掉底部盒子重量）</figcaption></figure><p>第二感觉是 —— 没那么好用。</p><p>展开凳子时，虽然有弹力绳的牵引作用，每根金属管都迫不及待地想伸展开来，但其实金属管伸展开来，并不能迅速对上各自的管口，使用者还要再自己手动调整好。</p><figure class=\"ss-imgRows\" figcaption=\"实测打开时间为 40 秒，收纳时间为 20 秒\"><img src=\"https://cdnfile.sspai.com/2024/11/04/e60f2d75fe86dd51f2e7e6b0984c4a10.gif\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/e60f2d75fe86dd51f2e7e6b0984c4a10.gif\"/><img src=\"https://cdnfile.sspai.com/2024/11/04/1a1f81a0706a6de93292daddabfeacba.gif\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/1a1f81a0706a6de93292daddabfeacba.gif\"/></figure><p>而且从做工上来看，细节也是差强人意。</p><figure class=\"ss-imgRows\" figcaption=\"钢管与铆钉细节\"><img src=\"https://cdnfile.sspai.com/2024/11/04/edc7c8494f3b52f62ee4eb7f53bfed7e.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/edc7c8494f3b52f62ee4eb7f53bfed7e.jpg?imageView2/2/format/webp\"/><img src=\"https://cdnfile.sspai.com/2024/11/04/f73f8fd6b8a49aed2cbd3c86ae9c8f42.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/f73f8fd6b8a49aed2cbd3c86ae9c8f42.jpg?imageView2/2/format/webp\"/></figure><p>但我真的需要一把凳子，所以我相信可能是我踩雷了这个商品，而不是我踩雷了这整个品类，于是我继续搜索，最后给我找到了解决我痛点的产品，也就是城市波浪的铝合金折叠凳。</p><p>首先，解决重的问题。</p><p>无名款折叠凳的金属管，产品描述为加厚碳钢材质，而城市波浪的这款折叠凳，金属管为铝合金材质，因此解决了重量的问题，至少将重量减了一半。</p><figure class=\"image ss-img-wrapper\"><img src=\"https://cdnfile.sspai.com/2024/11/04/f444edf2b5f3d20585ed009dfaec0caa.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" data-original=\"https://cdnfile.sspai.com/2024/11/04/f444edf2b5f3d20585ed009dfaec0caa.jpg?imageView2/2/format/webp\"/><figcaption>实测重量：336g（已去掉底部盒子重量）</figcaption></figure><p>其次，解决使用不便的问题。</p><p>这一点我不知道是怎么解决的，但是城市波浪折叠凳确实更快速就能展开使用，我想可能弹力绳弹力更好占部分原因吧。</p><figure class=\"ss-imgRows\" figcaption=\"实测打开时间为 8 秒，收纳时间为 10 秒\"><img src=\"https://cdnfile.sspai.com/2024/11/04/e6184d791bc183aa8f0224fd0c6cdc0e.gif\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/e6184d791bc183aa8f0224fd0c6cdc0e.gif\"/><img src=\"https://cdnfile.sspai.com/2024/11/04/da738087991392a711a59db9ae879b7d.GIF\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/da738087991392a711a59db9ae879b7d.GIF\"/></figure><p>在做工细节上，也略胜于无名款。</p><figure class=\"ss-imgRows\" figcaption=\"铝合金管与铆钉细节\"><img src=\"https://cdnfile.sspai.com/2024/11/04/5ef0e433f2f95fdd8be68a4461685248.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/5ef0e433f2f95fdd8be68a4461685248.jpg?imageView2/2/format/webp\"/><img src=\"https://cdnfile.sspai.com/2024/11/04/8185ea4c37952012f7528bc5e228489a.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/8185ea4c37952012f7528bc5e228489a.jpg?imageView2/2/format/webp\"/></figure><p>除了解决以上两个问题，两款产品还有以下对比：</p><ul><li>坐面大小几乎一致，城市波浪的凳子高度比无名款更高。</li></ul><figure class=\"ss-imgRows\" figcaption=\"虽然两个产品描述的长宽不一样，但实测坐面横向与纵向长度差距并不大。\"><img src=\"https://cdnfile.sspai.com/2024/11/04/cdeb8590c76ab14ff8aa4855a9fce332.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/cdeb8590c76ab14ff8aa4855a9fce332.jpg?imageView2/2/format/webp\"/><img src=\"https://cdnfile.sspai.com/2024/11/04/07e024faec7942d3e78c7104c22af12b.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/07e024faec7942d3e78c7104c22af12b.jpg?imageView2/2/format/webp\"/></figure><figure class=\"image ss-img-wrapper\"><img src=\"https://cdnfile.sspai.com/2024/11/04/4766dd552729ed6564e42f4ee2fd4ae0.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" data-original=\"https://cdnfile.sspai.com/2024/11/04/4766dd552729ed6564e42f4ee2fd4ae0.jpg?imageView2/2/format/webp\"/><figcaption>城市波浪款比无名款更高，城市波浪产品描述高度为 29cm</figcaption></figure><ul><li>收纳大小，城市波浪的收纳体积更小，且收纳袋本身展开就是坐面，而无名款则是另附了一个袋子进行收纳，如果万一收纳袋丢失，那么凳子只能找别的方法进行收纳，放着的话它会自动打开。</li></ul><figure class=\"ss-imgRows\" figcaption=\"收纳大小与 Switch 进行对比，城市波浪款略长于 Switch，宽与 Switch 一致\"><img src=\"https://cdnfile.sspai.com/2024/11/04/574f1745d6d0a760b7062dca6ab039e9.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/574f1745d6d0a760b7062dca6ab039e9.jpg?imageView2/2/format/webp\"/><img src=\"https://cdnfile.sspai.com/2024/11/04/2b6eb61056dc5aa732979b838bffb45a.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/2b6eb61056dc5aa732979b838bffb45a.jpg?imageView2/2/format/webp\"/></figure><ul><li>至于承重能力，对于我一个体重不到 40kg 的人来说，就没有什么好说服力了，两款椅子都能坐，毕竟如果连我都坐不了的话，这些凳子就应该自觉退出坐椅市场。</li></ul><p>整体来说，入手城市波浪的这款折叠凳，是一个不错的选择，平时我只要放在背包侧袋就可以带着出门，随时取用了。当然不用局限于这个牌子，或许其它厂家的铝合金折叠凳也是类似的品质。</p><p>如果要说这款椅子唯一问题，那就是出在品牌身上。</p><p>购买前，我注意到同一个牌子下有两款几乎一样的折叠凳，差别只是一个是 160g，一个是 330g。既然一开始我就是冲着越轻越好买的，那我肯定选择产品描述为轻至 160g 的折叠凳，而不是产品描述为轻至 330g 的折叠凳，但我实际上收到的商品却是 330g 的。</p><p>而两款产品的价格是不一样的，160g 的比 330g 的略贵，相当于我用更贵的价格买到了更重的折叠凳，虽然最后与商家协商一致进行了差价退款，但是我不禁想，如果有人跟我一样，下单了更贵更轻的产品，却没有发现收到货的是便宜且重的另一款产品，那岂不是平白无故蒙受损失。</p><p>所以建议大家在购买此类产品，特别是主打重量轻的产品，收到货后一定要记得称重，免得货不对板。</p><h2>💬一派热议</h2><p>在上期第 180 期一派投票《<a href=\"https://sspai.com/bullet/1730268010\">晒出你的手机控制中心 </a>》中，共有 613 名派友热情参与，十分感谢！</p><p><strong>人物 </strong>(+69)</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/10/30/avatar/59ce9e9751eb0ff7f80a89298ac322c4.png?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/10/30/avatar/59ce9e9751eb0ff7f80a89298ac322c4.png?imageView2/2/format/webp\"/></figure><p><strong>xcsoft </strong>(+37)</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/10/31/avatar/2f229c6de3a2716ca67909d5702cabce.png?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/10/31/avatar/2f229c6de3a2716ca67909d5702cabce.png?imageView2/2/format/webp\"/></figure><p><strong>运营小丸子 </strong>(+28) 顶部是常用的开关选项，然后是播放器、音量亮度相机状态，再然后就是一些其他杂七杂八的选项。最下面两个分别是 peaks 和 grow 的，可以看我今天的状态</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/10/31/avatar/1f8b8dfff28506b5a6746e5e4944d513.png?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/10/31/avatar/1f8b8dfff28506b5a6746e5e4944d513.png?imageView2/2/format/webp\"/></figure><p><strong>文某君 </strong>(+9) 还没养成「从控制中心启动 app」的习惯。</p><p>希望下一项系统界面的小改进是「可以隐藏 Dock 栏背景」……</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/10/31/f4c5602ad43fa63222deabba64a73411.jpeg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/10/31/f4c5602ad43fa63222deabba64a73411.jpeg?imageView2/2/format/webp\"/></figure><p><strong>赞卡 </strong>(+9) 控制中心随时随地都有右侧下拉，可以高效、临时进行其他操作。</p><p>我只设置了一屏常用的按钮</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/10/30/5441343c1fa5c688ff0ade84c385b133.png?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/10/30/5441343c1fa5c688ff0ade84c385b133.png?imageView2/2/format/webp\"/></figure><p><strong>少数派_803079 </strong>(+6)</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/10/30/avatar/feefb0abb3eb58fcb66a74979a4f4ddc.png?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/10/30/avatar/feefb0abb3eb58fcb66a74979a4f4ddc.png?imageView2/2/format/webp\"/></figure><p><strong>hap </strong>(+4)</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/11/01/3d544b55368c91b278bc1f88b4b8e44d.PNG?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/01/3d544b55368c91b278bc1f88b4b8e44d.PNG?imageView2/2/format/webp\"/></figure><p><strong>WZ 一 </strong>(+2) 有个 bug 不知道有没有人也遇到过，控制中心的组件有时候会随机消失一两个</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/11/10/avatar/344584f1d13c9a58a00f87b75b8fcd6d.png?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/10/avatar/344584f1d13c9a58a00f87b75b8fcd6d.png?imageView2/2/format/webp\"/></figure><p><strong>Niki92 </strong>(+1) 好玩</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/11/05/a804b86b1e84bb03569d1406a543200d.jpg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/05/a804b86b1e84bb03569d1406a543200d.jpg?imageView2/2/format/webp\"/></figure><p><strong>少数派 38192506 </strong>(+0) 比较简陋</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/11/11/avatar/70f4ceeb0f34e7056e0693fcc4a519fd.png?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/11/avatar/70f4ceeb0f34e7056e0693fcc4a519fd.png?imageView2/2/format/webp\"/></figure><p><strong>ASIIIO </strong>(+0) 都是些常用功能，放在左边是因为左手拿手机</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/11/04/avatar/e72df819a32a08d08595866e8b8e52dd.png?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/avatar/e72df819a32a08d08595866e8b8e52dd.png?imageView2/2/format/webp\"/></figure><p><strong>Gerley </strong>(+0) 专门做了一个快捷指令来切换双卡</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/11/04/avatar/205731cca034e2c5a161370e08e4d10d.png?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/04/avatar/205731cca034e2c5a161370e08e4d10d.png?imageView2/2/format/webp\"/></figure><p><strong>小明你给我出去 2333 </strong>(+0) hyper，但一点点不一样</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><img src=\"https://cdnfile.sspai.com/2024/11/03/avatar/6b86ad99cc2e942b6eb5f9610d80cfa8.jpeg?imageView2/2/w/1120/q/90/interlace/1/ignore-error/1/format/webp\" alt=\"\" data-original=\"https://cdnfile.sspai.com/2024/11/03/avatar/6b86ad99cc2e942b6eb5f9610d80cfa8.jpeg?imageView2/2/format/webp\"/></figure><p><strong>lh </strong>(+0) 全部控件整齐排列</p><figure class=\"image ss-img-wrapper image_resized\" style=\"width:500px;\"><im